// config.js: what the shared map-quiz engine (main.js, contract.js) needs
// to know about Japan Quiz: the data (japan.js, generated by
// tools/build_map.py) and every text the engine shows. Static text (title,
// help, button labels before the script runs) is in index.html. Contract:
// shared/map-quiz/README.md.
//
// The map is cut into pieces (PIECES: each prefecture's part on its main
// island, plus an <id>-isles piece where it has islands off it); every
// round's answers are groups of pieces. A piece in no answer of a round is
// inert there: in the islands round, everything off Honshū, Hokkaidō,
// Kyūshū and Shikoku (the -isles pieces, Okinawa).
import { MAP, PIECES, ISLANDS, REGIONS, PREFECTURES } from './japan.js';

const misclicks = (n) => (n ? ` · ${n} misclick${n === 1 ? '' : 's'}` : ' · no misclicks');
// The card's second line: the asked name in kanji and hiragana.
const reading = (e) => `${e.kanji} · ${e.kana}`;
const kanji = (e) => e.kanji;
const CAPITALS = PREFECTURES.filter((p) => p.capitalDiffers).length; // 18: the capital's name isn't the prefecture's
const COASTS = ['coast-main', 'coast-isles'];
const ALL_LINES = [...COASTS, 'borders-prefectures', 'borders-regions'];

export default {
  map: MAP,
  items: PIECES,
  rounds: [
    {
      key: 'islands',
      label: 'Islands',
      prompt: 'Find the island',
      answers: ISLANDS,
      lines: ['coast-main'],
      ask: (i) => i.name,
      sub: reading,
      subLang: 'ja',
      miss: (i) => i.name,
      missSub: kanji,
      done: ({ total, misses }) => `All ${total} islands found${misclicks(misses)}. Now the ${REGIONS.length} regions.`,
    },
    {
      key: 'regions',
      label: 'Regions',
      prompt: 'Find the region',
      answers: REGIONS,
      lines: [...COASTS, 'borders-regions'],
      ask: (r) => r.name,
      sub: reading,
      subLang: 'ja',
      miss: (r) => r.name,
      missSub: kanji,
      done: ({ total, misses }) => `All ${total} regions found${misclicks(misses)}. Now the ${PREFECTURES.length} prefectures.`,
    },
    {
      key: 'prefectures',
      label: 'Prefectures',
      prompt: 'Find the prefecture',
      answers: PREFECTURES,
      lines: ALL_LINES,
      ask: (p) => p.name,
      sub: reading,
      subLang: 'ja',
      miss: (p) => p.name,
      missSub: kanji,
      done: ({ total, misses }) =>
        `All ${total} prefectures found${misclicks(misses)}. Now ${CAPITALS} capitals: find each one's prefecture.`,
    },
    {
      key: 'capitals',
      label: 'Capitals',
      prompt: 'Find the prefecture whose capital is',
      answers: PREFECTURES,
      asked: (p) => p.capitalDiffers, // the others are misclicks this round
      lines: ALL_LINES,
      ask: (p) => p.capital,
      sub: (p) => `${p.capitalKanji} · ${p.capitalKana}`,
      subLang: 'ja',
      miss: (p) => `${p.name} · ${p.capital}`,
      missSub: (p) => `${p.kanji} · ${p.capitalKanji}`,
      done: ({ total, misses }) => `All ${total} capitals found${misclicks(misses)}. Islands again, in a new order.`,
    },
  ],
  text: {
    intro: {
      mouse: 'Click what the card names: islands first, then regions, prefectures, capitals. Zoom: mouse wheel or pinch. Move: drag or two-finger scroll.',
      touch: 'Tap what the card names: islands first, then regions, prefectures, capitals. Pinch to zoom, drag to move.',
    },
    newGame: 'New game: counters at zero, islands first.',
    reset: 'Reset the quiz',
    resetArmed: 'Really reset? Counters and colours are cleared',
    mapError: 'The map could not be loaded. Reload the page to try again.',
    theme: (other, override) => ({
      label: `Switch to ${other} theme`,
      title: override ? `Back to the system setting (${other})` : `Switch to the ${other} theme`,
    }),
  },
  view: { maxScale: 6, besideHud: true },
};
